update public.products p
set external_image_url=r.replacement_url, image_attribution=r.attribution, image_source_url=r.source_url
from review r
where p.id=r.product_id and p.source_product_name=r.billing_name
  and p.external_image_url is not distinct from r.previous_url
  and coalesce(p.image_path,'')='';
commit;
